const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Sakha (Yakutia) region - approximate bounding box
  const sakhaGeometry = ee.Geometry.Polygon([
    [[124, 62], [131, 62], [131, 66], [124, 66], [124, 62]]
  ]);

  // Summer 2021: June 1 - August 31, 2021
  const startDate = '2021-06-01';
  const endDate = '2021-08-31';

  // Use MODIS Burned Area product (MCD64A1)
  const burnedArea = ee.ImageCollection('MODIS/006/MCD64A1')
    .filterDate(startDate, endDate)
    .filterBounds(sakhaGeometry);

  const size = burnedArea.size().getInfo();
  console.log(`Burned Area Images found: ${size}`);

  if (size === 0) {
    console.log('No MODIS burned area data for Sakha summer 2021.');
    console.log('C1');
    return;
  }

  // Mosaic the monthly burned area images
  const mosaicBurned = burnedArea.select('BurnDate').mosaic();

  // Create a binary mask of burned pixels (BurnDate > 0 means burned)
  const burnedPixels = mosaicBurned.gt(0);

  // Count burned pixels in the region
  const pixelStats = burnedPixels.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sakhaGeometry,
    scale: 500,
    maxPixels: 1e9
  });

  const burnedPixelCount = pixelStats.get('BurnDate').getInfo();
  console.log(`Burned pixels detected: ${burnedPixelCount}`);

  if (burnedPixelCount === null || burnedPixelCount === 0) {
    console.log('No valid burned pixels in Sakha for summer 2021.');
    console.log('C2');
    return;
  }

  // Convert pixels to hectares (MODIS 500m resolution = 25 hectares per pixel)
  const pixelAreaHa = 0.25 * 0.25 * 100; // 500m x 500m = 25 hectares
  const totalBurnedHa = burnedPixelCount * pixelAreaHa;
  const totalBurnedMha = totalBurnedHa / 1e6;

  console.log(`Total burned area: ${totalBurnedMha.toFixed(2)} million hectares`);
  console.log(`Threshold: 6.0 million hectares`);

  if (totalBurnedMha === null || isNaN(totalBurnedMha)) {
    console.log('Calculation invalid.');
    console.log('C3');
    return;
  }

  if (totalBurnedMha >= 6.0) {
    console.log('Answer: At least 6 million hectares burned in Sakha summer 2021');
    console.log('A');
  } else {
    console.log('Answer: Less than 6 million hectares burned in Sakha summer 2021');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
